functions._alpSections:
function _alpSections() {
  return [
    // ─── Proprietary (encrypted) ─────────────────────────────────────────
    // BD Templates was here — REMOVED 2026-05-22. Templates now publish
    // via Template Manager as per-template sharded files at
    // eli-data/bd-templates/<id>.json. The monolithic bd_templates.enc.json
    // path is retired; admin_library_publisher should NOT push it anymore
    // (would conflict with the new sharded system + ship stale data).
    { key: "playbooks",      storeName: "playbooks",         manifestId: "__data_playbooks_proprietary",     filename: "playbooks.enc.json",    label: "Playbooks",                   confidential: true },
    { key: "requesters",     storeName: "requesters",        manifestId: "__data_requesters_proprietary",    filename: "requesters.enc.json",   label: "Requesters",                  confidential: true },
    { key: "riskRules",      storeName: "risk_rules",        manifestId: "__data_risk_rules_proprietary",    filename: "riskRules.enc.json",    label: "Risk Rules",                  confidential: true },
    { key: "templates",      storeName: "templates",         manifestId: "__data_templates_proprietary",     filename: "templates.enc.json",    label: "Compare Draft Templates",     confidential: true },
    // ─── Public (plaintext) ──────────────────────────────────────────────
    { key: "catalog",        storeName: "catalog",           manifestId: "__data_catalog",                   filename: "catalog.json",          label: "Master Catalog (tiles)",      confidential: false },
    { key: "prompts",        storeName: "prompts",           manifestId: "__data_prompts",                   filename: "prompts.json",          label: "AI Prompts",                  confidential: false },
    { key: "agreementTypes", storeName: "agreement_types",   manifestId: "__data_agreement_types",           filename: "agreement_types.json",  label: "Agreement Types",             confidential: false },
    { key: "execBriefTerms", storeName: "exec_brief_terms",  manifestId: "__data_exec_brief_terms",          filename: "exec_brief_terms.json", label: "Exec Brief Terms",            confidential: false },
    { key: "emailTemplates", storeName: "email_templates",   manifestId: "__data_email_templates",           filename: "email_templates.json",  label: "Email Templates",             confidential: false },
    { key: "cleanerRules",   storeName: "cleaner_rules",     manifestId: "__data_cleaner_rules",             filename: "cleaner_rules.json",    label: "Cleaner Rules",               confidential: false },
    { key: "loadingMsgs",    storeName: "loading_msgs",      manifestId: "__data_loading_msgs",              filename: "loading_msgs.json",     label: "Loading Messages",            confidential: false },
    { key: "trophies",       storeName: "trophies",          manifestId: "__data_trophies",                  filename: "trophies.json",         label: "Trophies",                    confidential: false }
  ];
}

// v3: pull PAT/repo/branch from MAIN settings (credentials token populates
// these on import). No more duplicate inputs in this tool — one source of
// truth. eli.compat tolerates iframe storage errors.

functions._alpLsGet:
function _alpLsGet(k) {
  try { return window.eli && window.eli.compat && window.eli.compat.lsGet ? (window.eli.compat.lsGet(k) || "") : ""; }
  catch (e) { return ""; }
}
// _alpLsSet removed 2026-05-14 — its only call sites (the post-publish
// eli_dataReleasedAt_*/eli_sectionDataId_*/eli_dataIdSections_* mirrors)
// were dropped; no live v3 code reads those keys.
// All three come from the encrypted credentials token, set into
// localStorage on import. No hardcoded fallbacks — the repo identity
// is confidential and should never appear in source code.

functions._alpStrToB64:
function _alpStrToB64(s) {
  var bytes = new TextEncoder().encode(s);
  var bin = "";
  for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

// GET /repos/.../contents/<path> → returns parsed JSON content + sha (or null
// if 404). Used to fetch the existing manifest before update, and to pick up
// the SHA needed to PUT an existing file.

functions._alpGitHubGet:
function _alpGitHubGet(pat, repo, branch, filePath) {
  // Defeat the browser cache so retry GETs see GitHub's current SHA, not
  // a cached stale one. Two non-preflight-triggering mechanisms:
  //   - cache: "no-store" — fetch-level directive, doesn't add headers
  //   - ?t=Date.now() — unique URL per call so cache key never matches
  // (Earlier we tried adding Cache-Control / Pragma headers; GitHub's
  // CORS preflight didn't allow them, breaking GET entirely. Don't add
  // non-safe-listed headers here.)
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath +
    "?ref=" + encodeURIComponent(branch) + "&t=" + Date.now();
  return fetch(url, {
    cache: "no-store",
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    },
  }).then(function (r) {
    if (r.status === 404) return null;
    if (!r.ok) return r.text().then(function (t) { throw new Error("GET " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}

// PUT /repos/.../contents/<path> — creates or updates a file. Pass existingSha
// from a prior GET to update; omit to create new.
//
// 2026-05-19: jsdelivr CDN cache purge after every successful PUT.
// Without this, jsdelivr keeps serving the OLD cached version for
// hours (default TTL is generous). Colleagues' refresh-data pulled
// stale files — admin would push templates dated today, colleagues
// would receive yesterday's templates. Purge is fire-and-forget so
// a purge-server hiccup never fails the actual GitHub push.

functions._alpGitHubPut:
function _alpGitHubPut(pat, repo, branch, filePath, contentStr, message, existingSha) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath;
  var body = {
    message: message,
    content: _alpStrToB64(contentStr),
    branch: branch,
  };
  if (existingSha) body.sha = existingSha;
  // 2026-05-20: auto-retry on the "Restricts updates to workflow files"
  // 403 timeout. GitHub's branch protection rule has to scan the diff
  // to verify no workflow files were touched — for large encrypted
  // bundles (bd_templates can be 20MB+) that scan exceeds its 10s
  // budget and returns 403. The retry succeeds because the rule
  // evaluator caches state from the first attempt. We retry up to
  // 3 times with exponential backoff (1.5s, 3s, 6s).
  function _doPut(attempt) {
    return fetch(url, {
      method: "PUT",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    }).then(function (r) {
      if (r.ok) return r.json();
      return r.text().then(function (t) {
        // Detect the workflow-rule-timeout 403 and retry.
        var isRuleTimeout = r.status === 403 && (
          /Restricts updates to workflow files/i.test(t) ||
          /Rule was unable to be completed/i.test(t)
        );
        if (isRuleTimeout && attempt < 3) {
          var delay = 1500 * Math.pow(2, attempt - 1); // 1.5s, 3s, 6s
          try { console.warn("[admin-library-publisher] PUT " + filePath + " 403 rule-timeout (attempt " + attempt + "/3) — retrying in " + (delay / 1000) + "s"); } catch (_e) {}
          return new Promise(function (resolve) { setTimeout(resolve, delay); })
            .then(function () { return _doPut(attempt + 1); });
        }
        throw new Error("PUT " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200));
      });
    });
  }
  return _doPut(1).then(function (result) {
    // Purge jsdelivr cache (fire-and-forget). Two URL shapes — purge the
    // branch ref AND the latest tag, since colleagues may fetch via either.
    var purgeBranchUrl = "https://purge.jsdelivr.net/gh/" + repo + "@" + branch + "/" + filePath;
    var purgeLatestUrl = "https://purge.jsdelivr.net/gh/" + repo + "/" + filePath;
    return Promise.all([
      fetch(purgeBranchUrl).catch(function () {}),
      fetch(purgeLatestUrl).catch(function () {}),
    ]).then(function () { return result; });
  });
}

// Build the upload payload for a section. For confidential sections this
// AES-GCM-encrypts the envelope with the library cipher; for public sections
// it returns the plaintext envelope JSON ready to PUT as-is.
// v3: no version arg — sectionVersions still gets a numeric value (the
// timestamp ms) so the kernel's per-section version-stamp check has a
// monotonically increasing value, but the user-facing API is just "push".
// 2026-05-18 v29: split into smaller helpers so the push step can
// pull-merge-push (prevent multi-admin overwrite) and optionally
// scope by selected row IDs (push just NDA, not the whole library).
//
// _alpReadLocalRows  — read just the rows from IDB, filtered for "_"-prefixed metadata.
// _alpReadRemoteRows — GET the CDN file, decrypt if confidential, parse rows + sha.
// _alpMergeRows      — per-id merge: selected local rows win; everything else keeps remote.
// _alpBuildPayloadFromRows — wrap a row list in the envelope shape + encrypt if needed.
// _alpBuildSectionPayload  — back-compat wrapper that reads local rows and builds the payload.

functions._alpReadLocalRows:
function _alpReadLocalRows(sectionKey) {
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  if (!sec) return Promise.reject(new Error("unknown section: " + sectionKey));
  return window.eli.storage.getAll(sec.storeName).then(function (rows) {
    return (rows || []).filter(function (r) {
      return r && typeof r === "object" && r.id && String(r.id).charAt(0) !== "_";
    });
  });
}

functions._alpReadRemoteRows:
function _alpReadRemoteRows(pat, repo, branch, sec) {
  // Returns { rows, sha } — empty rows + null sha if remote doesn't exist yet.
  return _alpGitHubGet(pat, repo, branch, sec.filename).then(function (existing) {
    if (!existing) return { rows: [], sha: null };
    var b64 = String(existing.content || "").replace(/\s/g, "");
    if (!b64) return { rows: [], sha: existing.sha || null };
    var bytes = Uint8Array.from(atob(b64), function (c) { return c.charCodeAt(0); });
    var str = new TextDecoder().decode(bytes);
    var envelope;
    try {
      var parsed = JSON.parse(str);
      if (sec.confidential) {
        var cipher = (typeof window._eliGetLibraryCipher === "function") ? window._eliGetLibraryCipher() : "";
        if (!cipher) throw new Error("library cipher missing — can't decrypt remote for merge");
        if (typeof window._eliDecryptFromRepo !== "function") throw new Error("_eliDecryptFromRepo unavailable");
        envelope = window._eliDecryptFromRepo(cipher, parsed);
      } else {
        envelope = parsed;
      }
    } catch (e) {
      // Decode/parse/decrypt failure → treat remote as empty (caller's
      // local data wins, no merge possible). Log so the user sees why.
      return { rows: [], sha: existing.sha || null, error: (e && e.message) || String(e) };
    }
    var rows = (envelope && envelope.sections && envelope.sections[sec.key]) || [];
    if (!Array.isArray(rows)) rows = [];
    return { rows: rows, sha: existing.sha || null };
  });
}
// 2026-05-19: bd_templates content-key dedup. The merge above is
// id-keyed — fine for libraries with deterministic ids (playbooks,
// templates, etc.), but bd_templates accumulated timestamp-id
// duplicates pre-v3 that all have DIFFERENT ids despite being the
// same template. This pass collapses by content-key
// (agreementType + type + party) and keeps the newest row per group
// so the pushed file has exactly one row per real template.

functions._alpDedupeBdTemplates:
function _alpDedupeBdTemplates(rows) {
  var byKey = {};
  (rows || []).forEach(function (r) {
    if (!r) return;
    var k = String(r.agreementType || "").toLowerCase().trim() +
            "::" + String(r.type || "") +
            "::" + String(r.party || "").toLowerCase().trim();
    var prev = byKey[k];
    var t = Number(r.timestamp) || 0;
    var prevT = prev ? (Number(prev.timestamp) || 0) : -1;
    if (!prev || t > prevT) byKey[k] = r;
  });
  return Object.keys(byKey).map(function (k) { return byKey[k]; });
}

functions._alpMergeRows:
function _alpMergeRows(localRows, remoteRows, selectedIdSet) {
  // selectedIdSet: object mapping id → true for rows the user explicitly
  // wants to push from local. If null, ALL local rows count as selected.
  // Rules:
  //   - Remote-only row → keep remote (someone else's work).
  //   - Local row in selectedIdSet → local wins (this user's edit).
  //   - Local row NOT in selectedIdSet → keep remote version if any, else local.
  var byId = {};
  (remoteRows || []).forEach(function (r) { if (r && r.id) byId[r.id] = r; });
  (localRows || []).forEach(function (r) {
    if (!r || !r.id) return;
    if (!selectedIdSet || selectedIdSet[r.id]) {
      byId[r.id] = r;
    } else if (!byId[r.id]) {
      // Local row exists but unselected AND not in remote → first push of
      // a row that the user didn't pick. Keep their local copy so it
      // doesn't get silently dropped.
      byId[r.id] = r;
    }
  });
  return Object.keys(byId).map(function (k) { return byId[k]; });
}

functions._alpBuildPayloadFromRows:
function _alpBuildPayloadFromRows(sectionKey, rows) {
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  if (!sec) return Promise.reject(new Error("unknown section: " + sectionKey));
  var cipher = "";
  if (sec.confidential) {
    cipher = (typeof window._eliGetLibraryCipher === "function") ? window._eliGetLibraryCipher() : "";
    if (!cipher) return Promise.reject(new Error("no library cipher set — Settings → Global → 📦 LIBRARY CIPHER"));
  }
  rows = (Array.isArray(rows) ? rows : []).filter(function (r) {
    return r && r.id && String(r.id).charAt(0) !== "_";
  });
  var nowIso = new Date().toISOString();
  var envelope = {
    schemaVersion: 1,
    exportedAt: nowIso,
    __releasedAt: nowIso,
    sectionVersions: {},
    sections: {},
  };
  envelope.sectionVersions[sectionKey] = Date.now();
  envelope.sections[sectionKey] = rows;
  var plaintextSize = JSON.stringify(envelope).length;
  if (!sec.confidential) {
    var plainJson = JSON.stringify(envelope, null, 2);
    return Promise.resolve({
      json: plainJson,
      byteSize: new TextEncoder().encode(plainJson).length,
      rowCount: rows.length,
      plaintextSize: plaintextSize,
      encrypted: false,
    });
  }
  return window._eliEncryptForRepo(cipher, envelope).then(function (encrypted) {
    var encJson = JSON.stringify(encrypted, null, 2);
    return {
      json: encJson,
      byteSize: new TextEncoder().encode(encJson).length,
      rowCount: rows.length,
      plaintextSize: plaintextSize,
      encrypted: true,
    };
  });
}
// Back-compat: any code path that still calls the old single-shot
// builder gets the full local payload, no merge (legacy behavior).

functions._alpBuildSectionPayload:
function _alpBuildSectionPayload(sectionKey) {
  return _alpReadLocalRows(sectionKey).then(function (rows) {
    return _alpBuildPayloadFromRows(sectionKey, rows);
  });
}

// Full publish flow for one section: encrypt → PUT blob → fetch+update+PUT
// manifest. Returns a result object for the UI log. No version arg —
// timestamps drive everything now.
// 2026-05-18 v29: signature gained `selectedRowIds` (array of row ids
// the user picked to push). null/undefined = push all local rows.
// Flow is now pull-merge-push: GET remote → decrypt → per-id merge
// (selected local wins) → re-encrypt → PUT. Prevents the multi-admin
// "last writer wins" overwrite where two admins editing DIFFERENT
// rows of the same library clobbered each other.

functions._alpPushOne:
function _alpPushOne(sectionKey, commitNote, logEl, selectedRowIds) {
  var pat = _alpGetPat(); if (!pat) return Promise.reject(new Error("no GitHub PAT — import credentials token via main Settings → Import Credentials"));
  var repo = _alpGetRepo(); var branch = _alpGetBranch();
  if (!repo) return Promise.reject(new Error("no GitHub repo configured — import credentials token via main Settings → Import Credentials"));
  if (!branch) return Promise.reject(new Error("no GitHub branch configured — import credentials token via main Settings → Import Credentials"));
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  var append = function (msg) {
    if (logEl) {
      logEl.innerHTML += '<div style="display:block; width:100%; font-size:11px; color:#cbd5e1; margin-top:2px; word-break:break-word;">' + msg + '</div>';
      logEl.scrollTop = logEl.scrollHeight;
    }
  };
  // Build the selected-id set (null = all local rows).
  var selectedSet = null;
  if (Array.isArray(selectedRowIds) && selectedRowIds.length) {
    selectedSet = {};
    selectedRowIds.forEach(function (id) { if (id) selectedSet[id] = true; });
  }
  append("📦 [" + sec.label + "] reading local rows…");
  // 2026-05-19: bd_templates is now a FULL-REPLACE library — admin's
  // local IDB IS the entire library, no merge with remote. Skips the
  // remote fetch + merge entirely. If admin deleted a template, the
  // next push will NOT silently bring it back from the CDN copy.
  // Colleagues' kernels also clear-and-replace on download, so the
  // result is: admin's local set EXACTLY = CDN file = colleague's
  // local set. No old/orphaned rows anywhere.
  //
  // Other libraries (playbooks, compare templates, riskRules, etc.)
  // KEEP the merge-with-remote semantic so each user's contributions
  // accumulate — that's the right pattern for shared rule sets that
  // multiple people edit.
  var FULL_REPLACE_SECTIONS = { bd_templates: true };
  var isFullReplace = !!FULL_REPLACE_SECTIONS[sectionKey];
  return _alpReadLocalRows(sectionKey).then(function (localRows) {
    var selectedLocalCount = selectedSet
      ? localRows.filter(function (r) { return selectedSet[r.id]; }).length
      : localRows.length;
    append("✓ " + localRows.length + " local rows total · " + selectedLocalCount + " selected to push");
    var mergedPromise;
    if (isFullReplace) {
      append("🔄 [" + sec.label + "] FULL REPLACE mode — skipping remote merge. Local set IS the entire library.");
      var localOnly = selectedSet
        ? localRows.filter(function (r) { return r && r.id && selectedSet[r.id]; })
        : localRows.slice();
      // Still content-dedup in case admin's local has timestamp-id
      // duplicates from the pre-deterministic-id era.
      var beforeCount = localOnly.length;
      var deduped = _alpDedupeBdTemplates(localOnly);
      if (deduped.length !== beforeCount) {
        append("🧹 Dedup: " + beforeCount + " → " + deduped.length + " (kept newest per template)");
      }
      mergedPromise = Promise.resolve(deduped);
    } else {
      append("⬇️ Fetching existing " + sec.filename + " from CDN to merge…");
      mergedPromise = _alpReadRemoteRows(pat, repo, branch, sec).then(function (remote) {
        if (remote.error) {
          append("  ⚠ remote decode/decrypt failed (" + remote.error + ") — pushing local-only, no merge");
        } else {
          append("  ✓ remote has " + remote.rows.length + " row(s)" + (remote.sha ? " · sha " + remote.sha.slice(0, 8) + "…" : " · new file"));
        }
        var merged = _alpMergeRows(localRows, remote.rows, selectedSet);
        append("🔀 Merged: " + merged.length + " rows total");
        return merged;
      });
    }
    return mergedPromise.then(function (rowsToPush) {
      var verb = sec.confidential ? "Encrypting" : "Building plaintext envelope";
      append("📦 " + verb + " from " + rowsToPush.length + " row(s)…");
      return _alpBuildPayloadFromRows(sectionKey, rowsToPush);
    });
  }).then(function (payload) {
    var sizeMsg = payload.encrypted
      ? "✓ Encrypted: " + payload.rowCount + " rows · " + (payload.plaintextSize / 1024).toFixed(1) + " KB plaintext → " + (payload.byteSize / 1024).toFixed(1) + " KB ciphertext"
      : "✓ Built: " + payload.rowCount + " rows · " + (payload.byteSize / 1024).toFixed(1) + " KB plaintext envelope";
    append(sizeMsg);
    append("⬆️ Fetching existing " + sec.filename + " (for SHA)…");
    // Retry up to 3x on 409 SHA mismatch — the GET can return a SHA that's
    // already gone stale (GitHub contents API has its own cache, separate
    // from the file-content layer). Each retry re-fetches a fresh SHA.
    var stamp = new Date().toISOString();
    var msg = "Update " + sec.filename + " · " + stamp.slice(0, 19) + "Z · " + payload.rowCount + " rows" + (commitNote ? " · " + commitNote : "");
    var maxFilePushRetries = 3;
    var attempt = 0;
    var pushFile = function () {
      attempt++;
      return _alpGitHubGet(pat, repo, branch, sec.filename).then(function (existing) {
        var sha = existing && existing.sha;
        append((attempt > 1 ? "  (retry " + attempt + ") " : "") + (sha ? "found existing — sha " + sha.slice(0, 8) + "…" : "not present — creating new"));
        if (attempt === 1) append("⬆️ Pushing " + sec.filename + "…");
        return _alpGitHubPut(pat, repo, branch, sec.filename, payload.json, msg, sha).catch(function (err) {
          var errMsg = String(err && err.message || err);
          if (/HTTP 409/.test(errMsg) && attempt < maxFilePushRetries) {
            append("  ⚠ SHA conflict — re-fetching and retrying…");
            return new Promise(function (r) { setTimeout(r, 800 * attempt); }).then(pushFile);
          }
          throw err;
        });
      });
    };
    return pushFile().then(function () {
      append("✓ " + sec.filename + " pushed");
      append("⬆️ Updating manifest entry " + sec.manifestId + "…");
      // 2026-05-13 audit fix: previously the manifest PUT had no retry, so
      // if a second admin pushed between our GET and PUT, this would 409
      // and abort — leaving the file pushed but the manifest stale. Now
      // the manifest update is wrapped in the same 3-attempt re-fetch
      // loop as the file push above. Each retry re-reads the manifest
      // (fresh SHA + fresh tools[] array) and re-applies our patch on top.
      var manifestAttempt = 0;
      var maxManifestRetries = 3;
      var pushManifest = function () {
        manifestAttempt++;
        return _alpGitHubGet(pat, repo, branch, "tools-manifest-v3.json").then(function (manifestRes) {
          if (!manifestRes) throw new Error("manifest not found in repo");
          // GitHub Contents API returns content as base64. atob() yields a
          // BINARY string (each char is a byte 0-255), NOT a UTF-8-decoded
          // string. Without proper decoding here, multi-byte UTF-8 chars in
          // the manifest (em-dashes, mid-dots, emoji) get mojibake'd on
          // every read-modify-write cycle. Always decode through Uint8Array
          // + TextDecoder.
          var b64 = (manifestRes.content || "").replace(/\s/g, "");
          var manifestBytes = Uint8Array.from(atob(b64), function (c) { return c.charCodeAt(0); });
          var manifestStr = new TextDecoder().decode(manifestBytes);
          var manifestJson = JSON.parse(manifestStr);
          if (!Array.isArray(manifestJson.tools)) manifestJson.tools = [];
          // 2026-05-17 v23: three-step lookup to avoid creating
          // duplicate manifest entries when an existing entry was
          // assigned a different id by an earlier admin / migration:
          //   1. Match by id (the publisher's expected manifestId).
          //   2. Fallback: match by filename — preserves an existing
          //      entry's id + label rather than orphaning it next to
          //      a fresh entry. Fixes the bug where pushing a section
          //      whose existing manifest entry was named
          //      "__data_negotiation_playbooks_proprietary" added a
          //      second "__data_playbooks_proprietary" entry alongside,
          //      breaking installs that read the manifest by filename.
          //   3. Create new only if neither match exists.
          var entry = manifestJson.tools.find(function (t) { return t.id === sec.manifestId; });
          if (!entry) {
            entry = manifestJson.tools.find(function (t) { return t.filename === sec.filename; });
            if (entry) {
              append("  ✦ matched existing entry by filename (id=" + entry.id + ") — updating in place; publisher's manifestId (" + sec.manifestId + ") NOT applied to preserve historical id");
            }
          }
          if (!entry) {
            entry = {
              id: sec.manifestId,
              label: sec.label,
              filename: sec.filename,
              audience: ["all"],
            };
            manifestJson.tools.push(entry);
            append("  ✦ creating new manifest entry " + sec.manifestId + " (first push for this section)");
          }
          // v3: no version field — timestamps drive update detection.
          entry.size = payload.byteSize;
          entry.lastUpdated = new Date().toISOString();
          entry.changelog = payload.rowCount + " rows · pushed " + entry.lastUpdated.slice(0, 19) + "Z" + (commitNote ? " · " + commitNote : "");
          delete entry.version; // remove any stale version field
          manifestJson.lastUpdated = entry.lastUpdated;
          var newManifest = JSON.stringify(manifestJson, null, 2);
          if (manifestAttempt > 1) append("  (manifest retry " + manifestAttempt + ") sha " + (manifestRes.sha || "").slice(0, 8) + "…");
          return _alpGitHubPut(pat, repo, branch, "tools-manifest-v3.json", newManifest,
            "Refresh " + sec.manifestId, manifestRes.sha).catch(function (mfErr) {
              var mfMsg = String(mfErr && mfErr.message || mfErr);
